        return new Sink(createParts ? Rnd432v.CreateDatasetWriter(route, filePath, files, options)
            : Rnd432v.CreateDatasetWriter(route, files, options));
    }

    sealed class Sink(Rnd432v.DatasetWriter writer) : IRandomDatasetSink
    {
        public void Queue(object row) => writer.Queue((Rnd432v)row);
        public void Dispose() => writer.Dispose();
    }
}